/**
 * Icon assets for LooviIcon — app-cliente (Hugeicons via "DS Semantic Aliases").
 *
 * Input: SVG exports (24×24, format svg) of alias components from Figma file
 * `[DS] Icons — App Cliente` (4LsFOmHu3B25vXsDPjklWs), section 7003:12884.
 * Each alias component is named with the DS contract (`*-outline` / `*-filled`)
 * and holds the Hugeicons geometry, so the native Hugeicons name never reaches
 * the slot.
 *
 * Usage:
 *   node packages/flutter_ds/tool/extract_icons.mjs <dir-with-raw-exports>
 *   (raw file name = DS icon name, e.g. arrow-left-outline.svg)
 *
 * Output (do not edit by hand):
 *   assets/icons/app-cliente/<name>.svg     — only the alias group, color → currentColor
 *   lib/src/generated/loovi_icon_names.g.dart
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PKG = path.resolve(__dirname, '..');
const RAW = process.argv[2];
if (!RAW) throw new Error('Uso: node tool/extract_icons.mjs <pasta-com-exports>');
const OUT = path.join(PKG, 'assets/icons/app-cliente');
const OUT_DART = path.join(PKG, 'lib/src/generated/loovi_icon_names.g.dart');
// Source node ids (alias components) — kept in the generated catalog for traceability.
const NODE_IDS = JSON.parse(fs.readFileSync(path.join(__dirname, 'icon_alias_nodes.json'), 'utf8'));

/** Extract the balanced <g id="name" …>…</g> element. */
function extractGroup(svg, name) {
  const open = svg.indexOf(`<g id="${name}"`);
  if (open < 0) throw new Error(`grupo ${name} não encontrado no export`);
  const re = /<\/?g\b[^>]*>/g;
  re.lastIndex = open;
  let depth = 0;
  let m;
  while ((m = re.exec(svg))) {
    if (m[0].startsWith('</')) depth--;
    else if (!m[0].endsWith('/>')) depth++;
    if (depth === 0) return svg.slice(open, re.lastIndex);
  }
  throw new Error(`grupo ${name} sem fechamento`);
}

const defsOf = (svg) => (svg.match(/<defs>[\s\S]*<\/defs>/) || [''])[0];

const DS_INK = /(fill|stroke)="#(1A1E1F|4B4F55)"/gi; // text/primary, text/secondary → monochrome contract

fs.mkdirSync(OUT, { recursive: true });
const names = [];
for (const file of fs.readdirSync(RAW).filter((f) => f.endsWith('.svg')).sort()) {
  const name = file.replace(/\.svg$/, '');
  if (!/^[a-z0-9]+(-[a-z0-9]+)*-(outline|filled)$/.test(name)) throw new Error(`nome fora do contrato DS: ${name}`);
  const raw = fs.readFileSync(path.join(RAW, file), 'utf8');
  const group = extractGroup(raw, name).replace(DS_INK, '$1="currentColor"');
  const out = [
    '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">',
    group,
    defsOf(raw),
    '</svg>',
    '',
  ].join('\n');
  if (/#(1A1E1F|4B4F55)/i.test(group)) throw new Error(`${name}: cor fixa restante`);
  fs.writeFileSync(path.join(OUT, `${name}.svg`), out, 'utf8');
  names.push(name);
}

const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const L = [
  '// GENERATED by packages/flutter_ds/tool/extract_icons.mjs — do not edit by hand.',
  '// ignore_for_file: constant_identifier_names',
  '',
  '/// DS icon contract names available in this package (mode app-cliente).',
  '/// Source: alias components in Figma 4LsFOmHu3B25vXsDPjklWs (section 7003:12884).',
  'abstract final class LooviIcons {',
];
for (const n of names) {
  L.push(`  /// \`${n}\` — alias node ${NODE_IDS[n] ?? '?'}`);
  L.push(`  static const String ${camel(n)} = '${n}';`);
}
L.push('  /// Every icon name shipped with this package.');
L.push(`  static const Set<String> all = {${names.map((n) => camel(n)).join(', ')}};`);
L.push('}');
fs.mkdirSync(path.dirname(OUT_DART), { recursive: true });
fs.writeFileSync(OUT_DART, L.join('\n') + '\n', 'utf8');
console.log(`loovi_ds icons: ${names.length} → assets/icons/app-cliente + ${path.relative(PKG, OUT_DART)}`);
